//! Port of the `static inline` helpers of src/melee/gr/inlines.h that the per-stage gr TUs
//! expand (TARGET_PC branch): `Ground_StartMapAnim`, `Ground_InitMapCollAndAnim`,
//! `Ground_UpdateWindAndMapColl`, `Ground_SetupStageCallbacks`, `Ground_InitTargetStage`,
//! `GET_GROUND`. Generated by cref/gen_grt_stages.py (callee table in cref/grt_db.py); checked
//! against the C inlines (verbatim, compiled natively) through the TUs that expand them
//! (tests/tu_grt_stages.rs).
//!
//! Callees go through [`ext`]: TODO stubs named like the C functions, replaceable through
//! [`ext::HOOKS`]. Trap: `Ground_SetupStageCallbacks` binds the three callbacks with `Mex_GrBind`
//! on PC (an m-ex stage's table may hold guest addresses); the native pointer passes through.
#![allow(non_snake_case, non_upper_case_globals, clippy::missing_safety_doc)]

use core::ffi::c_void;
use core::mem::transmute;
use std::sync::RwLock;

use melee_types::{GObj_RenderFunc, Ground, HSD_GObj, HSD_GObjEvent, HSD_JObj, StageCallbacks, StageInfo};

pub mod ext {
    use super::*;

    /// grDisplay_801C5DB0 (gr/grdisplay.c): the render callback `Ground_SetupStageCallbacks` installs.
    /// Only its address is used here.
    pub unsafe extern "C" fn grDisplay_801C5DB0(_g: *mut HSD_GObj, _pass: i32) {
        { unsafe { let _ = crate::tu::grdisplay::grDisplay_801C5DB0(_g as _, _pass as _); } return; }
    }

    /// The callees of this TU (unported TUs). Each defaults to a TODO panic; a test or the game
    /// wires the real function by assigning [`HOOKS`].
    #[derive(Clone, Copy)]
    pub struct Hooks {
        pub grAnime_801C8138: unsafe fn(g: *mut HSD_GObj, m: i32, b: i32),
        pub Ground_InitMapColl: unsafe fn(j: *mut HSD_JObj, m: i32) -> i32,
        pub Ground_UpdateMapColl: unsafe fn(g: *mut HSD_GObj) -> i32,
        pub lb_800115F4: unsafe fn(),
        pub GObj_SetupGXLink: unsafe fn(g: *mut HSD_GObj, cb: GObj_RenderFunc, gx: u8, pri: u32),
        pub Mex_GrBind: unsafe fn(f: *mut c_void) -> *mut c_void,
        pub HSD_GObj_SetupProc: unsafe fn(g: *mut HSD_GObj, f: HSD_GObjEvent, pri: u8),
        pub stage_info: unsafe fn() -> *mut StageInfo,
        pub Ground_801C39C0: unsafe fn(),
        pub Ground_801C3BB4: unsafe fn(),
        pub Ground_801C4210: unsafe fn(),
        pub Ground_801C42AC: unsafe fn(),
    }
    unsafe fn todo_grAnime_801C8138(_g: *mut HSD_GObj, _m: i32, _b: i32) { { unsafe { let _ = crate::tu::granime::grAnime_801C8138(_g as _, _m as _, _b as _); } return; } }
    unsafe fn todo_Ground_InitMapColl(_j: *mut HSD_JObj, _m: i32) -> i32 { { return unsafe { crate::tu::ground::Ground_InitMapColl(_j as _, _m as _) as _ }; } }
    unsafe fn todo_Ground_UpdateMapColl(_g: *mut HSD_GObj) -> i32 { { return unsafe { crate::tu::ground::Ground_UpdateMapColl(_g as _) as _ }; } }
    unsafe fn todo_lb_800115F4() { { unsafe { let _ = melee_runtime::tu::lb_00F9::lb_800115F4(); } return; } }
    unsafe fn todo_GObj_SetupGXLink(_g: *mut HSD_GObj, _cb: GObj_RenderFunc, _gx: u8, _pri: u32) { unsafe { let _ = melee_runtime::tu::gobj_native::GObj_SetupGXLink(_g as _, _cb as _, _gx as _, _pri as _); } }
    // gw_Mex_GrBind: no m-ex blob is loaded here, so every callback is already a native pointer and passes through
    unsafe fn todo_Mex_GrBind(_f: *mut c_void) -> *mut c_void { _f }
    unsafe fn todo_HSD_GObj_SetupProc(_g: *mut HSD_GObj, _f: HSD_GObjEvent, _pri: u8) { unsafe { let _ = melee_runtime::tu::gobj_native::HSD_GObj_SetupProc(_g as _, _f as _, _pri as _); } }
    unsafe fn todo_stage_info() -> *mut StageInfo { unsafe { core::ptr::addr_of_mut!(crate::tu::ground::stage_info) } }
    unsafe fn todo_Ground_801C39C0() { { unsafe { let _ = crate::tu::ground::Ground_801C39C0(); } return; } }
    unsafe fn todo_Ground_801C3BB4() { { unsafe { let _ = crate::tu::ground::Ground_801C3BB4(); } return; } }
    unsafe fn todo_Ground_801C4210() { { unsafe { let _ = crate::tu::ground::Ground_801C4210(); } return; } }
    unsafe fn todo_Ground_801C42AC() { { unsafe { let _ = crate::tu::ground::Ground_801C42AC(); } return; } }
    impl Hooks {
        pub const fn todo() -> Hooks {
            Hooks {
                grAnime_801C8138: todo_grAnime_801C8138,
                Ground_InitMapColl: todo_Ground_InitMapColl,
                Ground_UpdateMapColl: todo_Ground_UpdateMapColl,
                lb_800115F4: todo_lb_800115F4,
                GObj_SetupGXLink: todo_GObj_SetupGXLink,
                Mex_GrBind: todo_Mex_GrBind,
                HSD_GObj_SetupProc: todo_HSD_GObj_SetupProc,
                stage_info: todo_stage_info,
                Ground_801C39C0: todo_Ground_801C39C0,
                Ground_801C3BB4: todo_Ground_801C3BB4,
                Ground_801C4210: todo_Ground_801C4210,
                Ground_801C42AC: todo_Ground_801C42AC,
            }
        }
    }
    pub static HOOKS: RwLock<Hooks> = RwLock::new(Hooks::todo());

    pub unsafe fn grAnime_801C8138(g: *mut HSD_GObj, m: i32, b: i32) {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).grAnime_801C8138;
        hook(g, m, b)
    }
    pub unsafe fn Ground_InitMapColl(j: *mut HSD_JObj, m: i32) -> i32 {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_InitMapColl;
        hook(j, m)
    }
    pub unsafe fn Ground_UpdateMapColl(g: *mut HSD_GObj) -> i32 {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_UpdateMapColl;
        hook(g)
    }
    pub unsafe fn lb_800115F4() {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).lb_800115F4;
        hook()
    }
    pub unsafe fn GObj_SetupGXLink(g: *mut HSD_GObj, cb: GObj_RenderFunc, gx: u8, pri: u32) {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).GObj_SetupGXLink;
        hook(g, cb, gx, pri)
    }
    pub unsafe fn Mex_GrBind(f: *mut c_void) -> *mut c_void {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Mex_GrBind;
        hook(f)
    }
    pub unsafe fn HSD_GObj_SetupProc(g: *mut HSD_GObj, f: HSD_GObjEvent, pri: u8) {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).HSD_GObj_SetupProc;
        hook(g, f, pri)
    }
    pub unsafe fn stage_info() -> *mut StageInfo {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).stage_info;
        hook()
    }
    pub unsafe fn Ground_801C39C0() {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_801C39C0;
        hook()
    }
    pub unsafe fn Ground_801C3BB4() {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_801C3BB4;
        hook()
    }
    pub unsafe fn Ground_801C4210() {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_801C4210;
        hook()
    }
    pub unsafe fn Ground_801C42AC() {
        let hook = HOOKS.read().unwrap_or_else(|e| e.into_inner()).Ground_801C42AC;
        hook()
    }
}

/// `GET_GROUND(gobj)`.
#[inline]
pub unsafe fn GET_GROUND(gobj: *mut HSD_GObj) -> *mut Ground {
    (*gobj).user_data.cast()
}

/// Resets the map's model to its base pose and starts animation set 0.
pub unsafe fn Ground_StartMapAnim(gobj: *mut HSD_GObj) {
    let gp = GET_GROUND(gobj);
    ext::grAnime_801C8138(gobj, (*gp).map_id as i32, 0);
}

/// Binds the map's collision joints to its model, then starts animation set 0.
pub unsafe fn Ground_InitMapCollAndAnim(gobj: *mut HSD_GObj) {
    let gp = GET_GROUND(gobj);
    let jobj = (*gobj).hsd_obj as *mut HSD_JObj;
    ext::Ground_InitMapColl(jobj, (*gp).map_id as i32);
    ext::grAnime_801C8138(gobj, (*gp).map_id as i32, 0);
}

/// Advances the dynamics wind/force list, then re-syncs the map's collision joints.
pub unsafe fn Ground_UpdateWindAndMapColl(gobj: *mut HSD_GObj) {
    ext::lb_800115F4();
    ext::Ground_UpdateMapColl(gobj);
}

/// TARGET_PC `Ground_SetupStageCallbacks`.
pub unsafe fn Ground_SetupStageCallbacks(gobj: *mut HSD_GObj, callbacks: *mut StageCallbacks) {
    let gp = GET_GROUND(gobj);
    (*gp).x8_callback = None;
    (*gp).xC_callback = None;
    let render: GObj_RenderFunc = Some(ext::grDisplay_801C5DB0);
    ext::GObj_SetupGXLink(gobj, render, 3, 0);
    if (*callbacks).callback3.is_some() {
        let f = ext::Mex_GrBind((*callbacks).callback3.map_or(core::ptr::null_mut(), |f| f as *mut c_void));
        (*gp).x1C_callback = transmute::<*mut c_void, HSD_GObjEvent>(f);
    }
    if (*callbacks).on_init.is_some() {
        let f = ext::Mex_GrBind((*callbacks).on_init.map_or(core::ptr::null_mut(), |f| f as *mut c_void));
        if let Some(f) = transmute::<*mut c_void, HSD_GObjEvent>(f) {
            f(gobj);
        }
    }
    if (*callbacks).gobj_proc.is_some() {
        let f = ext::Mex_GrBind((*callbacks).gobj_proc.map_or(core::ptr::null_mut(), |f| f as *mut c_void));
        ext::HSD_GObj_SetupProc(gobj, transmute::<*mut c_void, HSD_GObjEvent>(f), 4);
    }
}

/// `Ground_InitTargetStage`: the common `OnInit` of the target-test stages.
pub unsafe fn Ground_InitTargetStage(create_gobj: unsafe extern "C" fn(i32) -> *mut HSD_GObj) {
    let si = ext::stage_info();
    (*si).unk8C.set_b4(0);
    (*si).unk8C.set_b5(1);
    create_gobj(0);
    create_gobj(1);
    create_gobj(2);
    ext::Ground_801C39C0();
    ext::Ground_801C3BB4();
    ext::Ground_801C4210();
    ext::Ground_801C42AC();
}
